    m_type = t_s.upper()
    if m_type not in {"RCV", "SHP", "RTN", "ADJ"}:
        raise ValueError(f"unknown type: {m_type}")

    sku = normalize_sku(s_s)
    z, a, s, l = parse_location(l_s)
    loc = f"{z.upper()}-{a:02d}-{s:02d}-{l}"

    cs = case_sizes.get(sku, 1)
    qty = parse_quantity(q_s, cs)

    if m_type in {"RCV", "SHP", "RTN"} and qty <= 0:
        raise ValueError(f"\"{m_type}" quantity must be positive")
    if m_type == "ADJ" and qty == 0:
        raise ValueError("ADJ quantity cannot be zero")

    final_qty = qty
    if m_type == "SHP":
        final_qty = -qty

    return {"day": day, "type": m_type, "sku": sku, "location": loc, "qty": final_qty}"}}, "messages": []}

